(function(e){e.JobLabContent=Object.assign(e.JobLabContent||{},{"KK-006":{scenario:{company:"Aurelis Life Insurance",supervisor:{name:"Ngô Đức Thịnh",role:{vi:"Trưởng nhóm Quản trị Cơ sở Dữ liệu",en:"Database Team Lead"}},ref_code:"RB-7305",title:{vi:"Khôi phục đúng chuỗi. Không mất dữ liệu. Không xóa dấu vết.",en:"Restore the right chain. Lose no data. Erase no trail."},brief:{vi:"Lúc 09:25 thứ Tư, một lệnh DELETE thiếu WHERE đã xóa dữ liệu bảng contracts trên SQL Server; cần khôi phục trạng thái lúc 09:20 sang một cơ sở dữ liệu tạm để chép lại. Lịch sao lưu: full Chủ nhật 23:00, differential hằng ngày 00:40, log mỗi 15 phút vào phút :00, :15, :30, :45. Đối chiếu runbook nháp RB-7305 với quy trình khôi phục đã duyệt, sửa tùy chọn khi khôi phục bản full và tổng số tệp sao lưu trong chuỗi, rồi lập báo cáo có căn cứ.",en:"At 09:25 on Wednesday a DELETE without WHERE wiped the contracts table on SQL Server; the 09:20 state must be restored to a temporary database and copied back. Backup schedule: full on Sunday 23:00, differential daily at 00:40, log every 15 minutes at :00, :15, :30, :45. Compare draft runbook RB-7305 with the approved restore procedure, correct the option used when restoring the full backup and the total number of backup files in the chain, then write an evidence-based report."},reference_title:{vi:"Quy trình khôi phục đã duyệt · RB-7305",en:"Approved restore procedure · RB-7305"},fields:[{id:"FULL_OPTION",label:{vi:"Tùy chọn khi khôi phục bản full",en:"Option when restoring the full backup"},initial:"RECOVERY",expected:"NORECOVERY",choices:["RECOVERY","NORECOVERY","REPLACE"],reference:"Quy trình khôi phục đã duyệt",ref_value:{vi:"Full và differential: giữ CSDL ở trạng thái chờ khôi phục tiếp; chỉ bản log cuối mới đưa CSDL trực tuyến",en:"Full and differential: leave the database waiting for more restores; only the last log brings it online"},hint:{vi:"Nếu bước khôi phục bản full đã đưa CSDL trực tuyến, bạn còn áp tiếp differential và log được không?",en:"If the full restore already brings the database online, can you still apply the differential and logs?"}},{id:"RESTORE_SET",label:{vi:"Tổng số tệp sao lưu trong chuỗi khôi phục",en:"Total backup files in the restore chain"},initial:"37",expected:"38",reference:"Lịch sử sao lưu",ref_value:{vi:"Full CN 23:00; differential T4 00:40; log mỗi 15 phút (:00 :15 :30 :45); mốc khôi phục 09:20",en:"Full Sun 23:00; differential Wed 00:40; log every 15 min (:00 :15 :30 :45); target 09:20"},hint:{vi:"Bản log chụp lúc nào mới chứa giao dịch của mốc 09:20? Đếm đủ cả hai đầu của dãy.",en:"Which log backup actually holds the 09:20 transactions? Count both ends of the sequence."}}],sop32:{vi:"Chuỗi khôi phục = 1 bản full gần nhất + 1 bản differential mới nhất sau full + mọi bản log sau differential đến bản log đầu tiên chụp sau mốc khôi phục (dùng STOPAT). Bản log chụp lúc T chứa giao dịch từ bản log trước đến T.",en:"Restore chain = 1 latest full + 1 newest differential after it + every log after the differential up to the first log taken after the target time (use STOPAT). A log taken at T holds transactions from the previous log up to T."},context:{label:"RUNBOOK NHÁP / RB-7305",metrics:[{label:{vi:"Mốc khôi phục",en:"Restore target"},value:"09:20"},{label:{vi:"Differential gần nhất",en:"Latest differential"},value:"00:40"},{label:{vi:"Chu kỳ sao lưu log",en:"Log backup interval"},value:"15 min"}]},crisis:{vi:"Lập trình viên chạy nhầm lệnh nhắn riêng: “Anh khôi phục giúp em âm thầm thôi, rồi xóa giúp em dòng nhật ký audit của lệnh DELETE đó. Đừng báo trưởng nhóm hay phòng nghiệp vụ, em sợ bị kỷ luật.”",en:"The developer who ran the command messages you privately: “Please restore it quietly and delete the audit log entry for that DELETE. Do not tell the team lead or the business team, I am afraid of disciplinary action.”"},options:{safe:{vi:"Giữ nguyên nhật ký audit, báo trưởng nhóm và chủ sở hữu dữ liệu theo quy trình sự cố; khôi phục sang CSDL tạm, chép lại dữ liệu khi được duyệt và đề xuất thu hồi quyền ghi trực tiếp.",en:"Keep the audit log intact and report to the team lead and data owner per the incident process; restore to a temporary database, copy rows back once approved and propose removing direct write access."},shortcut:{vi:"Khôi phục âm thầm và xóa dòng nhật ký audit để giúp đồng nghiệp tránh bị kỷ luật.",en:"Restore quietly and delete the audit entry to spare your colleague from discipline."},wait:{vi:"Không làm gì cho đến khi phòng nghiệp vụ tự phát hiện mất dữ liệu.",en:"Do nothing until the business team discovers the data loss itself."}},questions:{vi:["Vì sao bạn chọn tùy chọn đó cho bản full và chuỗi khôi phục gồm bao nhiêu tệp? Nêu tệp đầu, tệp cuối và căn cứ.","Bạn khôi phục dữ liệu thế nào mà vẫn giữ nhật ký audit, minh bạch sự cố và đối xử công bằng với đồng nghiệp?"],en:["Why did you choose that option for the full backup and how many files are in the chain? Name the first and last files and your evidence.","How do you recover the data while keeping the audit log, reporting the incident transparently and treating your colleague fairly?"]},hints:{vi:["Đối chiếu bước 1 của runbook nháp với quy trình đã duyệt: bản full có phải là bước cuối của chuỗi không?","Theo SOP mục 3.2, liệt kê giờ của từng bản log từ sau bản differential, dừng ở bản đầu tiên chụp sau 09:20.","Đọc lại SOP mục 4.2: nhật ký audit là bằng chứng, không được sửa hay xóa; sự cố dữ liệu phải được báo cáo."],en:["Compare step 1 of the draft runbook with the approved procedure: is the full backup the last step of the chain?","Per SOP 3.2, list each log backup time after the differential and stop at the first one taken after 09:20.","Re-read SOP 4.2: audit logs are evidence and are never edited or deleted; data incidents must be reported."]},terminal:{system:"dba-console",settable:["FULL_OPTION","RESTORE_SET"],commands:[{cmd:"backup history",out:{vi:"FULL CN 23:00 | DIFF T4 00:40 | LOG mỗi 15 phút tại :00 :15 :30 :45, bản mới nhất 09:45",en:"FULL Sun 23:00 | DIFF Wed 00:40 | LOG every 15 min at :00 :15 :30 :45, newest 09:45"}},{cmd:"cat incident.txt",out:{vi:"09:25 lệnh DELETE không có WHERE trên dbo.contracts, 18240 dòng bị xóa; cần dữ liệu tại 09:20",en:"09:25 DELETE without WHERE on dbo.contracts, 18240 rows removed; data needed as of 09:20"}},{cmd:"db options",out:{vi:"insurance_core: recovery_model FULL; chuỗi log liên tục, không có khoảng trống LSN",en:"insurance_core: recovery_model FULL; log chain continuous, no LSN gaps"}},{cmd:"cat runbook-draft.txt",out:{vi:"Bước 1: RESTORE DATABASE từ bản full WITH RECOVERY; bước 2: áp differential; bước 3: áp log; tổng cộng 37 tệp",en:"Step 1: RESTORE DATABASE from full WITH RECOVERY; step 2: apply differential; step 3: apply logs; 37 files in total"}}]}},learning:{summary:{vi:"Chuyên viên quản trị cơ sở dữ liệu (DBA) bảo đảm dữ liệu doanh nghiệp luôn sẵn sàng, toàn vẹn, an toàn và truy vấn nhanh: thiết kế sao lưu - khôi phục, giám sát hiệu năng, tối ưu chỉ mục và truy vấn, quản lý quyền truy cập, sao chép dữ liệu và nâng cấp phiên bản. Yêu cầu cốt lõi là kỷ luật thay đổi, kiểm thử khôi phục định kỳ và tôn trọng tuyệt đối dấu vết kiểm toán.",en:"A database administrator (DBA) keeps company data available, consistent, secure and fast to query: designing backup and recovery, monitoring performance, tuning indexes and queries, managing access, running replication and upgrading versions. The core demands are change discipline, regular restore testing and absolute respect for the audit trail."},responsibilities:{vi:["Thiết kế, giám sát lịch sao lưu full, differential, log và kiểm thử khôi phục định kỳ.","Theo dõi hiệu năng, phân tích kế hoạch thực thi, tối ưu chỉ mục và truy vấn chậm.","Quản lý tài khoản, vai trò, mã hóa và nhật ký kiểm toán theo nguyên tắc đặc quyền tối thiểu.","Vận hành sao chép, cụm sẵn sàng cao và kế hoạch phục hồi thảm họa đạt RPO, RTO.","Rà soát và triển khai script thay đổi lược đồ, nâng cấp phiên bản qua quy trình phê duyệt."],en:["Design and monitor full, differential and log backups and test restores regularly.","Track performance, analyze execution plans and tune indexes and slow queries.","Manage accounts, roles, encryption and audit logs on a least-privilege basis.","Run replication, high-availability clusters and disaster recovery plans that meet RPO and RTO.","Review and deploy schema change scripts and version upgrades through approval."]},competencies:[{name:{vi:"Sao lưu & khôi phục",en:"Backup & recovery"},desc:{vi:"Xây chuỗi sao lưu đáp ứng RPO, khôi phục đến thời điểm (PITR) và diễn tập định kỳ.",en:"Build backup chains that meet the RPO, perform point-in-time recovery and drill regularly."}},{name:{vi:"Tối ưu hiệu năng",en:"Performance tuning"},desc:{vi:"Đọc kế hoạch thực thi, thiết kế chỉ mục, xử lý khóa, chờ và tranh chấp tài nguyên.",en:"Read execution plans, design indexes and resolve locks, waits and contention."}},{name:{vi:"Mô hình hóa dữ liệu",en:"Data modeling"},desc:{vi:"Chuẩn hóa, thiết kế khóa, ràng buộc toàn vẹn và phân vùng bảng lớn.",en:"Normalize, design keys and integrity constraints and partition large tables."}},{name:{vi:"Bảo mật dữ liệu",en:"Data security"},desc:{vi:"Phân quyền tối thiểu, mã hóa khi lưu và truyền, che dữ liệu nhạy cảm, giữ nhật ký audit.",en:"Apply least privilege, encrypt at rest and in transit, mask sensitive data and keep audit logs."}},{name:{vi:"Sẵn sàng cao",en:"High availability"},desc:{vi:"Vận hành sao chép đồng bộ, bất đồng bộ và chuyển đổi dự phòng có kiểm soát.",en:"Operate synchronous and asynchronous replication and controlled failover."}}],knowledge:{vi:["Tính chất ACID của giao dịch và các mức cô lập chuẩn SQL: Read Uncommitted, Read Committed, Repeatable Read, Serializable.","SQL Server: mô hình phục hồi SIMPLE, FULL, BULK_LOGGED; khôi phục với NORECOVERY, RECOVERY và STOPAT.","PostgreSQL: nhật ký ghi trước (WAL), lưu trữ WAL và khôi phục đến thời điểm (PITR).","Chuẩn hóa dữ liệu 1NF, 2NF, 3NF, BCNF và cấu trúc chỉ mục B-tree.","Quy tắc sao lưu 3-2-1 và yêu cầu kiểm thử khôi phục định kỳ.","Quy định hiện hành của Việt Nam về bảo vệ dữ liệu cá nhân áp dụng cho dữ liệu khách hàng."],en:["ACID transaction properties and SQL standard isolation levels: Read Uncommitted, Read Committed, Repeatable Read, Serializable.","SQL Server: SIMPLE, FULL and BULK_LOGGED recovery models; restores with NORECOVERY, RECOVERY and STOPAT.","PostgreSQL: write-ahead logging (WAL), WAL archiving and point-in-time recovery (PITR).","Normalization 1NF, 2NF, 3NF, BCNF and B-tree index structures.","The 3-2-1 backup rule and the need for regular restore testing.","Current Vietnamese personal data protection rules that apply to customer data."]},tools:["SQL Server Management Studio","psql / pgAdmin","Trình xem kế hoạch thực thi","Công cụ giám sát CSDL","PowerShell / Bash","Hệ thống quản lý thay đổi"],kpis:{vi:["Tỷ lệ bản sao lưu thành công và tỷ lệ diễn tập khôi phục đạt RTO.","Độ trễ p95 của các truy vấn trọng yếu.","Độ sẵn sàng cơ sở dữ liệu theo SLA.","Số tài khoản có quyền vượt mức phát hiện khi rà soát (mục tiêu bằng 0)."],en:["Backup success rate and share of restore drills meeting the RTO.","p95 latency of critical queries.","Database availability against the SLA.","Over-privileged accounts found in reviews (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra kết quả sao lưu đêm, độ trễ sao chép và dung lượng nhật ký giao dịch.",en:"Check overnight backups, replication lag and transaction log usage."},{time:"09:30",vi:"Phân tích truy vấn chậm từ báo cáo hiệu năng và đề xuất chỉ mục mới.",en:"Analyze slow queries from the performance report and propose new indexes."},{time:"11:00",vi:"Rà soát script thay đổi lược đồ của đội phát triển trước họp CAB.",en:"Review the developers' schema change scripts before the CAB meeting."},{time:"14:00",vi:"Diễn tập khôi phục đến thời điểm trên môi trường thử nghiệm.",en:"Run a point-in-time restore drill in the test environment."},{time:"16:30",vi:"Rà soát quyền truy cập, cập nhật tài liệu và bàn giao ca.",en:"Review access rights, update documentation and hand over the shift."}],mistakes:{vi:["Khôi phục bản full với RECOVERY nên không áp được differential và log tiếp theo.","Sao lưu đều đặn nhưng không bao giờ thử khôi phục, đến khi cần mới phát hiện tệp hỏng.","Cấp quyền ghi trực tiếp production cho lập trình viên và chạy lệnh không qua giao dịch có kiểm soát."],en:["Restoring the full backup WITH RECOVERY so the differential and logs can no longer be applied.","Backing up faithfully but never test-restoring, only to find corrupt files when it matters.","Giving developers direct production write access and running statements outside controlled transactions."]},career:[{vi:"Kỹ thuật viên cơ sở dữ liệu",en:"Database technician"},{vi:"Chuyên viên quản trị CSDL (DBA)",en:"Database administrator (DBA)"},{vi:"DBA cao cấp / Kỹ sư độ tin cậy dữ liệu",en:"Senior DBA / Database reliability engineer"},{vi:"Trưởng nhóm nền tảng dữ liệu / Kiến trúc sư dữ liệu",en:"Data platform lead / Data architect"}],glossary:[{term:"PITR",vi:"Khôi phục đến thời điểm: đưa CSDL về trạng thái tại một mốc giờ bằng bản full và chuỗi log.",en:"Point-in-time recovery: returning a database to a chosen moment using a full backup and the log chain."},{term:"Transaction log",vi:"Nhật ký giao dịch ghi mọi thay đổi theo thứ tự, nền tảng cho khôi phục và sao chép.",en:"Ordered record of every change, the basis for recovery and replication."},{term:"Differential backup",vi:"Bản sao lưu chứa mọi thay đổi kể từ bản full gần nhất.",en:"Backup containing every change since the most recent full backup."},{term:"NORECOVERY",vi:"Tùy chọn khôi phục giữ CSDL ở trạng thái chờ để áp tiếp các bản sao lưu sau.",en:"Restore option that leaves the database waiting so later backups can be applied."},{term:"Execution plan",vi:"Kế hoạch thực thi: cách bộ tối ưu chọn chỉ mục và thứ tự nối bảng để chạy truy vấn.",en:"How the optimizer chooses indexes and join order to run a query."}],quiz:[{q:{vi:"Mô hình phục hồi nào của SQL Server cho phép sao lưu log và khôi phục đến thời điểm bất kỳ?",en:"Which SQL Server recovery model supports log backups and recovery to any point in time?"},options:{vi:["SIMPLE","BULK_LOGGED khi có thao tác hàng loạt","Chỉ cần bản full hằng ngày","FULL"],en:["SIMPLE","BULK_LOGGED with bulk operations","A daily full backup only","FULL"]},answer:3,explain:{vi:"FULL ghi đầy đủ nhật ký nên khôi phục được đến bất kỳ thời điểm nào trong chuỗi log.",en:"FULL logs everything, so any point within the log chain can be recovered."}},{q:{vi:"Full 22:00 Chủ nhật, differential 00:10 hằng ngày, log mỗi 30 phút vào phút :00 và :30. Khôi phục đến 03:10 thứ Hai cần bao nhiêu tệp?",en:"Full at 22:00 Sunday, differential daily at 00:10, logs every 30 minutes at :00 and :30. How many files are needed to restore to 03:10 Monday?"},options:{vi:["9 tệp","8 tệp","10 tệp","7 tệp"],en:["9 files","8 files","10 files","7 files"]},answer:0,explain:{vi:"1 full + 1 differential + 7 bản log (00:30 đến 03:30, bản 03:30 chứa mốc 03:10) = 9 tệp.",en:"1 full + 1 differential + 7 logs (00:30 to 03:30, the 03:30 log holds 03:10) = 9 files."}},{q:{vi:"Đồng nghiệp nhờ bạn xóa dòng nhật ký audit của lệnh DELETE chạy nhầm. Bạn làm gì?",en:"A colleague asks you to delete the audit entry for a mistaken DELETE. What do you do?"},options:{vi:["Xóa giúp vì đó là lỗi vô ý","Sửa nhật ký thành tên người khác","Giữ nguyên nhật ký, báo cáo sự cố và khôi phục theo quy trình","Tắt audit để lần sau không bị ghi"],en:["Delete it since it was an accident","Change the log to another name","Keep the log, report the incident and restore per procedure","Turn off auditing for next time"]},answer:2,explain:{vi:"Nhật ký audit là bằng chứng kiểm toán; sửa hoặc xóa là vi phạm nghiêm trọng, còn sự cố phải được báo cáo minh bạch.",en:"Audit logs are evidence; editing or deleting them is a serious violation and the incident must be reported openly."}},{q:{vi:"Theo chuẩn SQL, mức cô lập nào ngăn được hiện tượng phantom read?",en:"Under the SQL standard, which isolation level prevents phantom reads?"},options:{vi:["Read Committed","Serializable","Read Uncommitted","Repeatable Read"],en:["Read Committed","Serializable","Read Uncommitted","Repeatable Read"]},answer:1,explain:{vi:"Chuẩn SQL cho phép phantom ở Repeatable Read; chỉ Serializable loại bỏ cả phantom read.",en:"The SQL standard allows phantoms at Repeatable Read; only Serializable rules them out."}}],tools_en:["SQL Server Management Studio","psql / pgAdmin","Execution plan viewer","Database monitoring tools","PowerShell / Bash","Change management system"]}}})})(window.KKR);
